[{c:'10101020',n:'Consulta gastroenterológica',tipo:'Consulta',dur:20,preco:200,custo:80,sala:'Consultório'},{c:'40202615',n:'Endoscopia digestiva alta',tipo:'Procedimento',dur:30,preco:650,custo:240,sala:'Procedimentos',prep:'Jejum de 8 horas'}].forEach(p=>{PROCEDIMENTOS.push(p);EX[p.c]={c:p.c,n:p.n,s:(p.tipo+' '+p.n+' '+p.c).toLowerCase(),m:'',p:p.preco,d:0,j:/jejum de (\d+)/i.test(p.prep||'')?8:0,u:0,k:p.custo,proc:p.tipo,prep:p.prep||'Sem preparo',dur:p.dur}});
