 if(s.st==='chamada')return `Chamada ${s.nCham}x · ${esc(s.local)}`;if(s.st==='atendimento')return `${esc(s.local)} · desde ${s.hIni}`;if(s.st==='cancelada')return 'Cancelada: '+esc(s.motivo||'');
 if(s.st==='finalizada'&&e)return `${esc((rcSetor(e.setor)||{n:'Sem setor'}).n)} · ${e.st==='espera'?'em espera':e.st==='atendimento'?'em atendimento':e.cx?'aguarda o Caixa':'pendente'}`;
