/* ---------- Fila de pré-agendamento (notas 8 e 29) ---------- */
const rcPreBadge=s=>({'Pendente':'warn','Em contato':'info','Agendado':'ok','Sem interesse':'neutral','Sem sucesso no contato':'err','Cancelado':'neutral'})[s]||'neutral';
function rcPreVaga(x){return RC.agendas.some(a=>a.prof===x.prof&&a.unid===x.unid&&(!x.proc||a.procs.includes(x.proc))&&rcProxVaga(a,RC_HOJE))}
function rcPreCriar(d){if(!rcPacCpf(d.cpf))return {erro:'Selecione o paciente.'};if(!d.prof)return {erro:'Selecione o profissional desejado.'};if(!d.proc)return {erro:'Selecione o procedimento.'};
 const dup=RC.pre.find(x=>x.cpf===d.cpf&&x.prof===d.prof&&x.proc===d.proc&&['Pendente','Em contato'].includes(x.st));if(dup)return {erro:'Já existe pré-agendamento aberto igual a este.'};
 const x={id:++RC.seqId,...d,unid:+d.unid,pac:rcPacCpf(d.cpf).n,data:RC_HOJE,st:'Pendente',resp:rcResp(),log:[]};RC.pre.unshift(x);rcHist(x,'pre','Pré-agendamento registrado',`${clProcNome(x.proc)}${x.per?' · '+x.per:''}${x.obs?' · '+x.obs:''}`,PROF(x.prof).n);return {ok:x}}
function rcPreNovo(){rc();const A=location.hash==='#agendamento'?RC.agd:{};const u=A.unid||RC.unid;
 openModal(`${mh('Novo pré-agendamento')}<div class="mb"><div class="formgrid"><div class="field"><label for="prP">Paciente <span class="req">*</span></label><select class="in" id="prP"><option value="">Selecione</option>${rcOpts(PACIENTES.filter(p=>p.ativo).map(p=>[p.cpf,p.n+' · '+cpfMask(p.cpf)]),A.cpf||'')}</select></div>
 <div class="field"><label for="prU">Unidade</label><select class="in" id="prU">${rcUnidOpts(u)}</select></div><div class="field"><label for="prM">Profissional desejado <span class="req">*</span></label><select class="in" id="prM"><option value="">Selecione</option>${rcProfOpts(A.prof||'')}</select></div>
 <div class="field"><label for="prC">Procedimento ou especialidade <span class="req">*</span></label><select class="in" id="prC"><option value="">Selecione</option>${rcOpts(PROCEDIMENTOS.map(p=>[p.c,p.n]),A.proc||'')}</select></div>
 <div class="field"><label for="prT">Preferência de horário</label><select class="in" id="prT">${rcOpts([['Qualquer horário','Qualquer horário'],['Manhã','Manhã'],['Tarde','Tarde']],'')}</select></div></div>
 <div class="field"><label for="prO">Observações</label><textarea class="in" id="prO" rows="2" style="height:auto"></textarea></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="rcPreSalvar()">Registrar</button></div>`,'wide')}
function rcPreSalvar(){const r=rcPreCriar({cpf:$('#prP').value,unid:$('#prU').value,prof:$('#prM').value,proc:$('#prC').value,per:$('#prT').value,obs:$('#prO').value.trim()});if(r.erro){toast(r.erro,'warn');return}closeModal();if(location.hash==='#pre-agendamento')reView();else location.hash='#pre-agendamento';toast('Pré-agendamento registrado na fila')}
function rcPreSt(id,st){const x=RC.pre.find(y=>y.id===id);if(!x)return;x.st=st;x.log.push(st+' às '+hhmm(new Date()));rcHist(x,'pre','Pré-agendamento: '+st,clProcNome(x.proc),PROF(x.prof).n);toast('Situação: '+st);reView()}
function rcPreAgendar(id){const x=RC.pre.find(y=>y.id===id);if(!x)return;Object.assign(RC.agd,{cpf:x.cpf,prof:x.prof,proc:x.proc,unid:String(x.unid),tab:'novo',pre:x.id});x.st='Em contato';location.hash='#agendamento'}
function rcPreRows(){const F=RC.preF,q=semAc(F.q.trim()),l=RC.pre.filter(x=>(!F.st||x.st===F.st)&&(!F.prof||x.prof===F.prof)&&(!q||semAc([x.pac,PROF(x.prof).n,clProcNome(x.proc),rcUnidNome(x.unid)].join(' ')).includes(q)));
 if(!l.length)return vazioLinha(7,'Nenhum pré-agendamento','Mude os filtros ou registre um novo.');
 return l.map(x=>{const ab=['Pendente','Em contato'].includes(x.st),vaga=ab&&rcPreVaga(x),pc=rcPacCpf(x.cpf)||{};return `<tr>${td('Paciente',`<div class="two">${esc(x.pac)}<small>${esc(pc.tel||'')}</small></div>`)}${td('Profissional e unidade',`<div class="two">${esc(PROF(x.prof).n)}<small>${esc(rcUnidNome(x.unid))}</small></div>`)}${td('Procedimento',`<div class="two">${esc(clProcNome(x.proc))}<small>${esc(x.per||'')}${x.obs?' · '+esc(x.obs):''}</small></div>`)}${td('Registro',`<div class="two">${rcDiaBr(x.data)}<small>${esc(x.resp||'')}</small></div>`)}${td('Agenda',vaga?'<span class="badge ok">Aberta com vaga</span>':'<span class="tl">Sem vaga</span>')}${td('Situação',`<select class="in" style="width:auto;height:28px;font-size:12px" aria-label="Situação de ${esc(x.pac)}" onchange="rcPreSt(${x.id},this.value)">${rcOpts(RC_PRE_ST.map(s=>[s,s]),x.st)}</select>`)}${td('',vaga?`<button class="btn sm" onclick="rcPreAgendar(${x.id})">Agendar</button>`:'')}</tr>`}).join('')}
VIEWS['pre-agendamento']=()=>{rc();const F=RC.preF,c=k=>RC.pre.filter(x=>x.st===k).length,comVaga=RC.pre.filter(x=>['Pendente','Em contato'].includes(x.st)&&rcPreVaga(x)).length;
 return `${pageHead('Recepção','Fila de Pré-agendamento','Quem quer atendimento e ainda não tem agenda ou horário. Retome o contato quando abrir.',`<a class="btn sec" href="#agendamento">Agendamento</a><button class="btn" onclick="rcPreNovo()">${I.plus} Novo pré-agendamento</button>`)}
 <div class="mini">${miniKpi('Pendentes',c('Pendente'),'aguardando contato','warn')}${miniKpi('Em contato',c('Em contato'),'em andamento')}${miniKpi('Podem agendar',comVaga,'agenda aberta com vaga','ok')}${miniKpi('Agendados',c('Agendado'),'atendimento marcado','ok')}</div>
 <div class="filters" style="margin-top:12px"><div class="inwrap" style="flex:1 1 220px">${LUPA}<input class="in" placeholder="Paciente, profissional, procedimento ou unidade" value="${esc(F.q)}" oninput="RC.preF.q=this.value;$('#rcPrB').innerHTML=rcPreRows()" aria-label="Buscar"></div><select class="in" style="width:auto" aria-label="Situação" onchange="RC.preF.st=this.value;$('#rcPrB').innerHTML=rcPreRows()"><option value="">Todas as situações</option>${rcOpts(RC_PRE_ST.map(s=>[s,s]),F.st)}</select><select class="in" style="width:auto" aria-label="Profissional" onchange="RC.preF.prof=this.value;$('#rcPrB').innerHTML=rcPreRows()"><option value="">Todos os profissionais</option>${rcProfOpts(F.prof)}</select></div>
 <div class="tablewrap"><table class="at-table"><thead><tr>${['Paciente','Profissional e unidade','Procedimento','Registro','Agenda','Situação',''].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody id="rcPrB">${rcPreRows()}</tbody></table></div>`};

/* ---------- Guia de Exames (nota 27) ---------- */
const RC_DUVIDAS=[['Quem precisa de jejum?','A ficha do exame mostra as horas de jejum. Em vários exames na mesma visita, vale o maior jejum.'],['Quanto tempo sai o resultado?','O prazo em dias úteis está na ficha. Urgência, quando existe, é em horas.'],['Posso tomar água em jejum?','Sim, água é liberada, salvo orientação do médico.'],['Como pedir exame de urgência?','Marque urgência no Novo atendimento. Nem todo exame aceita: veja na ficha.']];
function rcGeLista(){const G=RC.ge,q=semAc(G.q.trim());return Object.values(EX).filter(e=>e&&e.n&&(!q||semAc(e.n+' '+e.c+' '+(e.s||'')).includes(q))&&(!G.mat||(G.mat==='proc'?!!e.proc:e.m===G.mat))).sort((a,b)=>a.n.localeCompare(b.n))}
const rcPrazo=e=>e.proc?'No mesmo dia':!e.d?'Sob consulta':e.d===1?'1 dia útil':e.d+' dias úteis';
function rcGeRows(){const l=rcGeLista();if(!l.length)return vazioLinha(6,'Nenhum exame encontrado','Tente outro nome ou sinônimo.');
 return l.map(e=>`<tr style="cursor:pointer" onclick="rcGeVer('${e.c}')">${td('Exame',`<div class="two">${esc(e.n)}<small class="mono">${esc(e.c)}</small></div>`)}${td('Material',esc(e.m||e.proc||''))}${td('Preparo',esc(clPrepItem(e.c)||'Sem preparo'))}${td('Prazo',rcPrazo(e))}${td('Urgência',e.u?e.u+' h':'Não')}${td('Valor',fmt(e.p||0))}</tr>`).join('')}
function rcGeVer(c){const e=EX[c];if(!e)return;openDrawer(esc(e.n),kvs([['Código',`<span class="mono">${esc(e.c)}</span>`],['Também chamado',esc(e.s||'')],['Material',esc(e.m||'Não se aplica')],['Preparo',esc(clPrepItem(c)||'Sem preparo')],['Jejum',e.j?e.j+' horas':'Não precisa'],['Prazo',rcPrazo(e)],['Urgência',e.u?'Em até '+e.u+' h':'Não disponível'],['Valor particular',fmt(e.p||0)]])+`<div class="row" style="margin-top:12px"><button class="btn sec" onclick="closeDrawer();naNovo('orcamento')">Fazer orçamento</button></div>`)}
VIEWS['guia-exames']=()=>{rc();const G=RC.ge,mats=[...new Set(Object.values(EX).map(e=>e&&e.m).filter(Boolean))].sort();
 return `${pageHead('Recepção','Guia de Exames','Consulte preparo, material, prazo e valor para tirar dúvidas no balcão.')}
 ${rcTabs([['lista','Exames'],['duv','Dúvidas frequentes']],G.tab,'RC.ge.tab')}<div style="margin-top:12px">${G.tab==='duv'?`<div class="at-list">${RC_DUVIDAS.map(([q,r])=>`<div class="at-row"><div class="grow"><b>${q}</b><small>${r}</small></div></div>`).join('')}</div>`:`<div class="filters"><div class="inwrap" style="flex:1 1 240px">${LUPA}<input class="in" placeholder="Nome, sinônimo ou código" value="${esc(G.q)}" oninput="RC.ge.q=this.value;$('#rcGeB').innerHTML=rcGeRows()" aria-label="Buscar exame"></div><select class="in" style="width:auto" aria-label="Material" onchange="RC.ge.mat=this.value;$('#rcGeB').innerHTML=rcGeRows()"><option value="">Todos os materiais</option>${rcOpts(mats.map(m=>[m,m]),G.mat)}<option value="proc" ${G.mat==='proc'?'selected':''}>Consultas e procedimentos</option></select></div><div class="tablewrap"><table class="at-table"><thead><tr>${['Exame','Material','Preparo','Prazo','Urgência','Valor'].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody id="rcGeB">${rcGeRows()}</tbody></table></div>`}</div>`};

/* ---------- Configurações da recepção (notas 3, 4, 6 e 40) ---------- */
function rcTogLista(arr,v){const i=arr.indexOf(v);i>=0?arr.splice(i,1):arr.push(v);rcMudou()}
const rcCfgChips=(todos,sel,oc)=>`<div class="cl-jpick">${todos.map(([v,t])=>`<button type="button" class="chip ${sel.includes(v)?'on':''}" onclick="${oc.replace('#',v)}">${esc(t)}</button>`).join('')}</div>`;
function rcAddTipo(){const n=$('#cfT').value.trim(),p=$('#cfTP').value.trim().toUpperCase();if(!n||!p){toast('Informe nome e prefixo','warn');return}if(RC.cfg.tipos.some(t=>t.pref===p)){toast('Prefixo já usado','warn');return}RC.cfg.tipos.push({id:p,n,pref:p,ativo:true,unids:[RC.unid]});RC.cfg.guiches.forEach(g=>{if(g.unid===RC.unid)g.tipos.push(p)});rcMudou();toast('Tipo de senha criado')}
function rcAddPeso(){const n=$('#cfP').value.trim(),l=$('#cfPL').value.trim().toUpperCase(),v=+$('#cfPV').value;if(!n||!l||!v){toast('Informe nome, letra e valor','warn');return}if(RC.cfg.pesos.some(p=>p.letra===l)){toast('Letra já usada','warn');return}const id='P'+(++RC.seqId);RC.cfg.pesos.push({id,n,letra:l,valor:v,cor:'neutral',ativo:true,crit:'',unids:Object.keys(UNIDS).map(Number)});RC.cfg.guiches.forEach(g=>g.pesos.push(id));rcMudou();toast('Peso criado')}
function rcAddGuiche(){const q=rcGuiches().length+1;RC.cfg.guiches.push({id:'g'+(++RC.seqId),n:'Guichê '+q,op:'',unid:RC.unid,ativo:true,tipos:RC.cfg.tipos.map(t=>t.id),pesos:RC.cfg.pesos.map(p=>p.id)});rcMudou();toast(`Guichê ${q} criado`)}
function rcAddSetor(){const n=$('#cfS').value.trim();if(!n){toast('Informe o nome do setor','warn');return}RC.cfg.setores.push({id:'s'+(++RC.seqId),n,grupos:[],subs:[],procs:[],tipos:[],locais:[n],perfis:[]});rcMudou();toast('Setor criado')}
function rcSetGrupo(id,g,k='grupos'){const s=rcSetor(id),tem=s[k].includes(g);RC.cfg.setores.forEach(o=>o[k]=o[k].filter(x=>x!==g));if(!tem)s[k].push(g);rcMudou()}
function rcSeqPreset(k){RC.cfg.seq={a:['NOR','PRI'],b:['PRI','PRI','JEJ'],c:['ESP','PRI','NOR','PRI','JEJ','NOR']}[k];RC.ptr=0;rcMudou();toast('Sequência aplicada')}
const rcSeqPrevia=()=>{const dem=RC.cfg.pesos.filter(p=>p.ativo).flatMap(p=>[0,1,2].map(i=>({peso:p.id,ts:i}))).filter(x=>!RC.cfg.pesos.find(p=>p.id===x.peso).sempre);return rcOrdem(dem,RC.cfg,0).slice(0,8).map(x=>rcPeso(x.peso).n).join(' · ')};
VIEWS['config-recepcao']=()=>{rc();const c=RC.cfg,T=RC.cfgTab,PE=c.pesos.map(p=>[p.id,p.n]),TI=c.tipos.map(t=>[t.id,t.n]),UN=Object.keys(UNIDS).map(u=>[+u,rcUnidNome(u)]),SUB=[...new Set(Object.keys(EX).map(rcSubDe).filter(Boolean))].sort().map(x=>[x,x]);
 const corpo=T==='tipos'?`${tabela(['Tipo de senha','Prefixo','Unidades','Ativo'],c.tipos.map((t,i)=>`<tr>${td('Tipo de senha',esc(t.n))}${td('Prefixo',`<span class="mono">${esc(t.pref)}</span>`)}${td('Unidades',rcCfgChips(Object.keys(UNIDS).map(u=>[+u,rcUnidNome(u)]),t.unids,`rcTogLista(RC.cfg.tipos[${i}].unids,#)`))}${td('Ativo',rcSwitch(t.ativo,`RC.cfg.tipos[${i}].ativo=this.checked;rcMudou()`))}</tr>`))}<div class="filters" style="margin-top:10px"><input class="in" id="cfT" style="flex:1 1 200px" placeholder="Novo tipo de senha" aria-label="Nome do tipo"><input class="in" id="cfTP" style="width:90px" maxlength="2" placeholder="Prefixo" aria-label="Prefixo"><button class="btn sec" onclick="rcAddTipo()">Adicionar</button></div>`
 :T==='pesos'?`${tabela(['Peso do atendimento','Critério','Unidades','Letra','Valor','Sempre primeiro','Ativo'],c.pesos.map((p,i)=>`<tr>${td('Peso do atendimento',rcPesoTag(p.id))}${td('Critério',`<input class="in" value="${esc(p.crit||'')}" aria-label="Critério de ${esc(p.n)}" onchange="RC.cfg.pesos[${i}].crit=this.value">`)}${td('Unidades',rcCfgChips(UN,p.unids,`rcTogLista(RC.cfg.pesos[${i}].unids,#)`))}${td('Letra',`<span class="mono">${esc(p.letra||'nenhuma')}</span>`)}${td('Valor',`<input class="in" type="number" min="1" max="99" style="width:80px" value="${p.valor}" aria-label="Valor de ${esc(p.n)}" onchange="RC.cfg.pesos[${i}].valor=+this.value||1;rcMudou()">`)}${td('Sempre primeiro',rcSwitch(!!p.sempre,`RC.cfg.pesos[${i}].sempre=this.checked;rcMudou()`))}${td('Ativo',rcSwitch(p.ativo,`RC.cfg.pesos[${i}].ativo=this.checked;rcMudou()`))}</tr>`))}<div class="filters" style="margin-top:10px"><input class="in" id="cfP" style="flex:1 1 200px" placeholder="Novo peso" aria-label="Nome do peso"><input class="in" id="cfPL" style="width:80px" maxlength="1" placeholder="Letra" aria-label="Letra"><input class="in" id="cfPV" type="number" min="1" style="width:90px" placeholder="Valor" aria-label="Valor"><button class="btn sec" onclick="rcAddPeso()">Adicionar</button></div>`
 :T==='seq'?`<div class="card"><div class="field" style="max-width:360px"><label for="cfM">Ordem de chamada</label><select class="in" id="cfM" onchange="RC.cfg.modo=this.value;rcMudou()">${rcOpts([['seq','Sequência configurada'],['peso','Peso mais tempo de espera']],c.modo)}</select></div>
 ${c.modo==='seq'?`<h4 style="margin:10px 0 6px">Sequência</h4><div class="cl-jpick">${c.seq.map((k,i)=>`<button type="button" class="chip on" aria-label="Retirar ${esc(rcPeso(k).n)}" onclick="RC.cfg.seq.splice(${i},1);rcMudou()">${i+1}. ${esc(rcPeso(k).n)} ×</button>`).join('')||'<span class="tl">Sequência vazia: vale peso mais tempo de espera.</span>'}</div>
 <div class="row" style="margin-top:8px;gap:6px;flex-wrap:wrap"><select class="in" style="width:auto" aria-label="Incluir na sequência" onchange="if(this.value){RC.cfg.seq.push(this.value);rcMudou()}"><option value="">Incluir peso</option>${rcOpts(PE,'')}</select><button class="btn sm ghost" onclick="rcSeqPreset('a')">Normal e Prioridade</button><button class="btn sm ghost" onclick="rcSeqPreset('b')">Duas Prioridade e um Jejum</button><button class="btn sm ghost" onclick="rcSeqPreset('c')">Padrão</button></div>`:''}
 <p class="tl" style="margin-top:10px">Peso marcado como sempre primeiro passa na frente. Depois: <b>${esc(rcSeqPrevia())}</b></p></div>`
 :T==='guiches'?`<div class="switchrow" style="margin-bottom:10px"><span>Atende sem agendamento<small>Vale para ${esc(rcUnidNome(RC.unid))}.</small></span>${rcSwitch(c.semAg.includes(RC.unid),'rcTogLista(RC.cfg.semAg,RC.unid)')}</div>${tabela(['Guichê','Operador','Tipos','Pesos','Ativo'],rcGuiches().map(g=>{const i=c.guiches.indexOf(g);return `<tr>${td('Guichê',`<input class="in" style="width:120px" value="${esc(g.n)}" aria-label="Nome do guichê" onchange="RC.cfg.guiches[${i}].n=this.value||'Guichê';rcMudou()">`)}${td('Operador',`<input class="in" style="width:120px" value="${esc(g.op)}" aria-label="Operador" onchange="RC.cfg.guiches[${i}].op=this.value">`)}${td('Tipos',rcCfgChips(TI,g.tipos,`rcTogLista(RC.cfg.guiches[${i}].tipos,'#')`))}${td('Pesos',rcCfgChips(PE,g.pesos,`rcTogLista(RC.cfg.guiches[${i}].pesos,'#')`))}${td('Ativo',rcSwitch(g.ativo,`RC.cfg.guiches[${i}].ativo=this.checked;rcMudou()`))}</tr>`}),'Nenhum guichê nesta unidade')}<div class="row" style="margin-top:10px"><span class="tl">${rcGuiches().length} guichês em ${esc(rcUnidNome(RC.unid))}</span><button class="btn sec" onclick="rcAddGuiche()">${I.plus} Adicionar guichê</button></div>`
 :T==='setores'?`${tabela(['Setor','Grupos, subgrupos e procedimentos','Salas ou locais','Tipos de senha (vazio: todos)','Quem vê só este setor'],c.setores.map((s,i)=>`<tr>${td('Setor',esc(s.n))}${td('Grupos, subgrupos e procedimentos',`${rcCfgChips(RC_GRUPOS.map(g=>[g,g]),s.grupos,`rcSetGrupo('${s.id}','#')`)}<small class="tl" style="display:block;margin-top:6px">Subgrupos</small>${rcCfgChips(SUB,s.subs,`rcSetGrupo('${s.id}','#','subs')`)}<small class="tl" style="display:block;margin-top:6px">Procedimentos</small>${rcCfgChips(s.procs.map(x=>[x,clProcNome(x)]),s.procs,`rcSetGrupo('${s.id}','#','procs')`)}<select class="in" style="width:auto;margin-top:4px" aria-label="Incluir procedimento" onchange="if(this.value)rcSetGrupo('${s.id}',this.value,'procs')"><option value="">Incluir procedimento</option>${rcOpts(Object.values(EX).filter(e=>e&&e.n).map(e=>[e.c,e.n]),'')}</select>`)}${td('Salas ou locais',`<input class="in" value="${esc(s.locais.join(', '))}" aria-label="Locais de ${esc(s.n)}" onchange="RC.cfg.setores[${i}].locais=this.value.split(',').map(x=>x.trim()).filter(Boolean);rcMudou()">`)}${td('Tipos de senha',rcCfgChips(TI,s.tipos,`rcTogLista(RC.cfg.setores[${i}].tipos,'#')`))}${td('Quem vê só este setor',rcCfgChips(PERFIS.map(p=>[p[0],p[1]]).filter(p=>!ATENDE.includes(p[0])).slice(0,4),s.perfis||[],`rcTogLista(RC.cfg.setores[${i}].perfis,'#')`))}</tr>`))}<div class="filters" style="margin-top:10px"><input class="in" id="cfS" style="flex:1 1 200px" placeholder="Novo setor" aria-label="Nome do setor"><button class="btn sec" onclick="rcAddSetor()">Adicionar</button></div>`
 :`<div class="card"><div class="switchrow"><span>Pesquisa de satisfação ao finalizar<small>Vincula a senha à avaliação do paciente.</small></span>${rcSwitch(c.nps,'RC.cfg.nps=this.checked;rcMudou()')}</div><div class="field" style="max-width:240px;margin-top:10px"><label for="cfNC">Canal da pesquisa</label><select class="in" id="cfNC" onchange="RC.cfg.npsCanal=this.value">${rcOpts([['WhatsApp','WhatsApp'],['SMS','SMS'],['E-mail','E-mail']],c.npsCanal)}</select></div><div class="switchrow" style="margin-top:10px"><span>Chamada por voz<small>Anuncia só o nome do paciente e o local.</small></span>${rcSwitch(RC.voz,'RC.voz=this.checked')}</div></div>`;
 return `${pageHead('Configurações','Recepção',`Senhas, pesos, ordem de chamada, guichês e setores de ${rcUnidNome(RC.unid)}.`)}${rcTabs([['pesos','Pesos'],['tipos','Tipos de senha'],['seq','Ordem de chamada'],['guiches','Guichês'],['setores','Setores'],['painel','Painel e pesquisa']],T,'RC.cfgTab')}<div style="margin-top:12px">${corpo}</div>`};

