function rcTrocarUnidade(){rc();openModal(`${mh('Trocar de unidade')}<div class="mb"><div class="at-list">${Object.keys(UNIDS).map(u=>`<label class="at-row check"><input type="radio" name="rcUn" value="${u}" ${+u===RC.unid?'checked':''}><div class="grow">${esc(rcUnidNome(u))}${+u===RC.unid?'<small>Unidade atual</small>':''}</div></label>`).join('')}</div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="rcDefUnidade(+document.querySelector('input[name=rcUn]:checked').value)">Trocar</button></div>`)}
