 P('Marta Lima','P-003','PRI',12,'cancelada',{motivo:'Gerada por engano',hFim:rcH(Date.now()-600000)});
 P('Francisca Oliveira','A-011','NOR',7,'aguardando',{unid:14});P('Marcos Vinícius Rocha','A-005','PRI',3,'aguardando',{unid:12});
 RC.chamadas.push({sid:ch.id,num:ch.num,n:ch.pac,cod:rcCod(ch),peso:ch.peso,local:ch.local,unid:10,painel:'rec',h:ch.hCham,ts:Date.now()-120000},{sid:0,num:'A-079',n:'Pedro Lima',cod:'',peso:'NOR',local:'Guichê 1',unid:10,painel:'rec',h:'08:31',ts:Date.now()-900000},{sid:0,num:'P-002',n:'Marta Nogueira',cod:'',peso:'PRI',local:'Guichê 3',unid:10,painel:'rec',h:'08:22',ts:Date.now()-1200000});
 /* Quem já passou pelo guichê: fila da coleta (mesmas senhas da Home) e agenda de hoje */
